// Generates src/types/chapter.ts from ../schema/chapter.schema.json. The schema is the source of truth.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = fileURLToPath(new URL("..", import.meta.url));
const schemaPath = new URL("../../schema/chapter.schema.json", import.meta.url);
const outPath = new URL("../src/types/chapter.ts", import.meta.url);

const schema = JSON.parse(await readFile(schemaPath, "utf8"));
const banner = [
  "/**",
  " * GENERATED by `npm run gen:types` from schema/chapter.schema.json. Do not edit by hand.",
  " * Change the schema, log it in docs/decisions.md, then regenerate.",
  " */",
].join("\n");

const ts = await compile(schema, "Chapter", {
  bannerComment: banner,
  additionalProperties: false,
  unreachableDefinitions: true,
  cwd: root,
  format: true,
});
await writeFile(outPath, ts);
console.log(`wrote src/types/chapter.ts (${ts.split("\n").length} lines)`);
